const t = ($('Config (GET)').all().map((i) => i.json).find((r) => r && r.chave === 'QA_TOKEN') || {}).valor;
const w = $('Página (GET)').first().json;
const k = String((w.query || {}).k || '');
return [{ json: { ok: !!t && t.length >= 20 && k === t, k } }];

// ATOM2_05 · Painel de QA · página (Code node, "Run Once for All Items").
// Entrada: $('Ler auditorias'), $('Ler achados'), $('Ler empresas'); $('Token').first().json.k = token válido.
// Saída: 1 item { html } com a fila de QA (qa_status = pendente), mais fortes primeiro.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const k = $('Token').first().json.k;
// Só a auditoria pendente mais recente de cada empresa (um N1 refeito em outro dia não gera cartão duplicado).
const todas = $('Ler auditorias').all().map((i) => i.json).filter((a) => a && a.audit_id && a.qa_status === 'pendente');
const maisNova = {};
for (const a of todas) if (!maisNova[a.company_id] || String(a.observado_em) > String(maisNova[a.company_id].observado_em)) maisNova[a.company_id] = a;
const auds = Object.values(maisNova);
const achados = $('Ler achados').all().map((i) => i.json).filter((a) => a && a.finding_id);
const empresas = Object.fromEntries($('Ler empresas').all().map((i) => i.json).filter((e) => e && e.company_id).map((e) => [e.company_id, e]));
auds.sort((a, b) => (b.score || 0) - (a.score || 0));
const SEV = { alta: 'Alta', media: 'Média', baixa: 'Baixa' };

const cartao = (a) => {
  const e = empresas[a.company_id] || {};
  const lista = achados.filter((f) => f.audit_id === a.audit_id).sort((x, y) => (x.usado_em === 'principal' ? -1 : y.usado_em === 'principal' ? 1 : 0) || ['alta', 'media', 'baixa'].indexOf(x.severity) - ['alta', 'media', 'baixa'].indexOf(y.severity));
  const semOport = !a.mensagem_d1;
  return `<article class="card" data-audit="${esc(a.audit_id)}">
  <header><div><h2>${esc(e.nome || a.company_id)}</h2><p class="meta">${esc(e.cidade || '')}/${esc(e.uf || '')} · <a href="https://${esc(e.dominio)}" target="_blank" rel="noopener noreferrer">${esc(e.dominio)}</a> · ${esc(e.telefone || 'sem telefone')}</p></div>
  <div class="score faixa-${esc(a.faixa || 'C')}"><strong>${a.score ?? '—'}</strong><span>Faixa ${esc(a.faixa || '—')}</span></div></header>
  <details ${semOport ? '' : 'open'}><summary>${lista.length} achado(s) · observado em ${esc(String(a.observado_em || '').slice(0, 10))}</summary>
  <ul class="achados">${lista.map((f) => `<li class="${f.usado_em === 'principal' ? 'principal' : ''}"><span class="sev sev-${esc(f.severity)}">${SEV[f.severity] || esc(f.severity)}</span>${f.usado_em === 'principal' ? '<span class="tag">principal</span>' : ''}<p>${esc(f.claim)}</p><p class="ev">Evidência: ${esc(f.evidence)} · <a href="${esc(f.source_url)}" target="_blank" rel="noopener noreferrer">fonte</a> · confiança ${Math.round((f.confidence || 0) * 100)}%</p></li>`).join('')}</ul></details>
  ${semOport ? `<p class="aviso">Sem oportunidade verificada: não abordar com personalização. Reprove ou deixe para depois.</p>` : `
  <label>1º contato (recepção)<textarea name="d1" rows="3">${esc(a.mensagem_d1)}</textarea></label>
  <label>Mensagem ao decisor (com o achado; [Nome] é preenchido quando a recepção indicar)<textarea name="decisor" rows="4">${esc(a.mensagem_decisor || '')}</textarea></label>`}
  <label>Observação (opcional)<input name="obs" type="text" maxlength="300"></label>
  <div class="acoes">${semOport ? '' : '<button class="ok" data-acao="aprovar">Aprovar</button>'}<button class="nao" data-acao="reprovar">Reprovar</button><span class="status" role="status"></span></div>
</article>`;
};

const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>QA · Prospecção Ativa</title>
<style>
:root{--bg:#f6f7f9;--card:#fff;--tx:#1d2330;--mut:#5d6677;--bd:#e3e6ec;--ok:#1f7a4d;--no:#b42318;--alta:#b42318;--media:#b25e09;--baixa:#53627a;--pri:#2f5bd3}
@media (prefers-color-scheme:dark){:root{--bg:#12151b;--card:#1b2029;--tx:#e8ebf1;--mut:#9aa3b2;--bd:#2c3340;--pri:#7c9cff}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
main{max-width:920px;margin:0 auto;padding:24px 16px 64px}h1{font-size:22px;margin:0 0 4px}.sub{color:var(--mut);margin:0 0 20px}
.card{background:var(--card);border:1px solid var(--bd);border-radius:12px;padding:18px;margin:0 0 16px}.card.feito{opacity:.55}
header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}h2{font-size:18px;margin:0}.meta{color:var(--mut);margin:2px 0 0;font-size:13px;word-break:break-all}
.score{text-align:center;min-width:70px;border-radius:10px;padding:6px 8px;border:1px solid var(--bd)}.score strong{display:block;font-size:22px}.score span{font-size:12px;color:var(--mut)}
.faixa-A strong{color:var(--ok)}.faixa-C strong{color:var(--mut)}
details{margin:12px 0}summary{cursor:pointer;color:var(--mut)}.achados{list-style:none;padding:0;margin:8px 0 0}.achados li{border-left:3px solid var(--bd);padding:6px 10px;margin:6px 0}.achados li.principal{border-color:var(--pri)}
.achados p{margin:2px 0}.ev{font-size:12px;color:var(--mut);word-break:break-word}.sev{font-size:11px;font-weight:600;text-transform:uppercase;margin-right:6px}.sev-alta{color:var(--alta)}.sev-media{color:var(--media)}.sev-baixa{color:var(--baixa)}
.tag{font-size:11px;background:var(--pri);color:#fff;border-radius:4px;padding:1px 6px}
label{display:block;font-size:13px;color:var(--mut);margin:10px 0 0}textarea,input{width:100%;margin-top:4px;font:inherit;color:var(--tx);background:var(--bg);border:1px solid var(--bd);border-radius:8px;padding:8px}
.acoes{display:flex;gap:8px;align-items:center;margin-top:12px;flex-wrap:wrap}button{font:inherit;border:0;border-radius:8px;padding:8px 16px;cursor:pointer;color:#fff}button.ok{background:var(--ok)}button.nao{background:var(--no)}button:disabled{opacity:.5;cursor:default}
.status{font-size:13px;color:var(--mut)}.aviso{background:var(--bg);border-radius:8px;padding:8px;color:var(--mut)}.vazio{color:var(--mut);text-align:center;padding:40px}
</style></head><body><main>
<h1>QA · Prospecção Ativa</h1><p class="sub">${auds.length} diagnóstico(s) aguardando revisão. Nada é enviado daqui: aprovar libera a empresa para a fila (F3), que respeita o modo de execução. Mensagens com preço são recusadas (regra absoluta).</p>
${auds.length ? auds.map(cartao).join('') : '<p class="vazio">Fila vazia.</p>'}
</main><script>
const K=${JSON.stringify(k)};
document.querySelectorAll('button[data-acao]').forEach(b=>b.addEventListener('click',async()=>{
 const c=b.closest('.card'),st=c.querySelector('.status');c.querySelectorAll('button').forEach(x=>x.disabled=true);st.textContent='Salvando…';
 const v=n=>{const el=c.querySelector('[name='+n+']');return el?el.value:''};
 try{const r=await fetch(location.pathname+'-decisao?k='+encodeURIComponent(K),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({audit_id:c.dataset.audit,acao:b.dataset.acao,d1:v('d1'),decisor:v('decisor'),obs:v('obs')})});
  const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.erro||'erro '+r.status);st.textContent=j.mensagem;c.classList.add('feito');}
 catch(e){st.textContent='Não salvo: '+e.message;c.querySelectorAll('button').forEach(x=>x.disabled=false);}
}));
</script></body></html>`;
return [{ json: { html } }];

const t = ($('Config (POST)').all().map((i) => i.json).find((r) => r && r.chave === 'QA_TOKEN') || {}).valor;
const w = $('Decisão (POST)').first().json;
const k = String((w.query || {}).k || '');
return [{ json: { ok: !!t && t.length >= 20 && k === t, body: w.body || {} } }];

// ATOM2_05 · Painel de QA · decisão (Code node, "Run Once for All Items").
// Entrada: corpo do POST em $('Token POST').body { audit_id, acao: aprovar|reprovar, d1, decisor, obs } e $('Ler auditoria').
// Saída: 1 item { ok, erro?, mensagem, auditoria?, empresa?, evento? } — as gravações vêm depois, só se ok.
// Trava de preço (regra absoluta, lib_guarda_preco.js) e termos proibidos (W05) valem para o texto editado.
// <guarda> — bloco canônico: copiado idêntico para W05, W05b, W07 e W08 por n8n/tools/sync_guarda.js (teste confere).
// Fronteiras Unicode: \b do JavaScript não trata "é", "à" etc. como letra.
const I = '(?<![\\p{L}\\p{N}])', F = '(?![\\p{L}\\p{N}])';
const rx = (corpo) => new RegExp(I + corpo + F, 'iu');
const EXTENSO = '(um|uma|dois|duas|tr[eê]s|quatro|cinco|seis|sete|oito|nove|dez|onze|doze|treze|quatorze|catorze|quinze|dezesseis|dezessete|dezoito|dezenove|vinte|trinta|quarenta|cinquenta|sessenta|setenta|oitenta|noventa|cem|cento|duzentos|duzentas|trezentos|trezentas|quatrocentos|quinhentos|seiscentos|setecentos|oitocentos|novecentos)';
const PRECO_RX = [
  /(R|US|U)?\s*[$＄]\s*\d/i,                                                                   // R$ 3.000, R $3000, US$ 500, $500
  rx('\\d{1,3}([.\\s]\\d{3})+([.,]\\d{2})?'),                                                 // 3.000 / 14.000,00 / 1 500,00
  rx('\\d+([.,]\\d+)?\\s*(mil|reais|k)'),                                                     // 3 mil, 900 reais, 3k
  rx(EXTENSO + '(\\s+e\\s+' + EXTENSO + ')*\\s+(mil|reais)'),                                 // três mil, dois mil e quinhentos
  rx('\\d+,\\d{2}'), rx('\\d+\\.\\d{2}'),                                                     // 500,00 / 500.00
  rx('\\d+([.,]\\d+)?\\s*(/\\s*m[eê]s|por m[eê]s|mensais|ao m[eê]s|/\\s*ano|por ano)'),       // 1500/mês, 990 mensais
  rx('\\d+\\s*x\\s*(de\\s*)?(R\\$\\s*)?\\d+'),                                                 // 12x 300, 2x de 750
  rx('(valor|custo|taxa|or[cç]amento|ticket|plano|investimento)\\s*(:|mensal|anual|de|é|e|fica|sai|total|inicial)?\\s*(R\\$\\s*)?\\d+'), // Valor: 1500, orçamento de 1500
  rx('(?<!(oportunidades|resultados|dados|casos|problemas|ganhos|melhorias|clientes|pacientes|n[uú]meros|exemplos|situa[cç][oõ]es|pessoas|avalia[cç][oõ]es|depoimentos|evid[eê]ncias|mudan[cç]as|benef[ií]cios)\\s)reais'),
  rx('pre[cç]os?'),
  rx('valor(es)?\\s+(de|do|da|para|é|e|fica|sai|total|mensal)'),
  rx('investimento\\s+(de|é|e|fica|sai|total|inicial|mensal)'),
  rx('(mensalidade|parcelas?|parcelado|entrada de|setup de|desconto|à vista|a vista|boleto|pix)'),
  rx('(custa|custo de|cobramos|sai por|fica por|a partir de)')
];
// Promessas e alegações proibidas (handoff §8; scripts de 09/10). "Ninguém pode garantir isso" (script ChatGPT) passa.
const PROIBIDOS = [/primeira posi[cç][aã]o/i, /topo do google/i, /garant(imos|ido|idos|ida|idas|o\b|ia de)/i, /posi[cç][aã]o\s*\d/i, /\b\d+\s*(visitas|clientes|pacientes) (por|ao) m[eê]s/i, /preju[ií]zo/i, /queda de vendas/i, /perdendo (clientes|pacientes|vendas)/i, /cliente oculto/i, /chatgpt (indicou|citou|recomendou)/i];
const bloqueios = (t) => [...PRECO_RX.filter((r) => r.test(String(t || ''))).map(() => 'preço antes da proposta'), ...PROIBIDOS.filter((r) => r.test(String(t || ''))).map((r) => 'termo proibido ' + r.source)];
// </guarda>
const problemas = (t) => bloqueios(t).map((m) => (m.startsWith('preço') ? 'menciona preço (proibido antes da proposta)' : m));

const b = $('Token POST').first().json.body || {};
const aud = $('Ler auditoria').all().map((i) => i.json).find((a) => a && a.audit_id === b.audit_id);
const agora = new Date().toISOString();
const falha = (erro) => [{ json: { ok: false, erro } }];
if (!aud) return falha('auditoria não encontrada');
if (aud.qa_status !== 'pendente') return falha('já revisada (' + aud.qa_status + ')');
if (!['aprovar', 'reprovar'].includes(b.acao)) return falha('ação inválida');
const obs = String(b.obs || '').slice(0, 300);
const evento = (tipo) => ({ event_id: 'e_qa_' + aud.audit_id + '_' + tipo.toLowerCase(), correlation_id: aud.audit_id, company_id: aud.company_id, workflow: 'ATOM2_05', tipo, motivo: obs || tipo, dados: JSON.stringify({ por: 'Thiago' }), ocorrido_em: agora });

if (b.acao === 'reprovar') {
  return [{ json: { ok: true, mensagem: 'Reprovado.', auditoria: { audit_id: aud.audit_id, qa_status: 'reprovado', qa_por: 'Thiago', qa_em: agora, qa_obs: obs }, achados_status: 'reprovado',
    empresa: { company_id: aud.company_id, status_motivo: 'QA reprovado' + (obs ? ': ' + obs : ''), atualizado_em: agora }, evento: evento('QA_REPROVADO') } }];
}
const d1 = String(b.d1 || '').trim(), decisor = String(b.decisor || '').trim();
if (!aud.mensagem_d1) return falha('sem oportunidade verificada: não há mensagem para aprovar');
if (!d1 || d1.length > 700 || !decisor || decisor.length > 900) return falha('mensagens vazias ou longas demais');
const p = [...problemas(d1), ...problemas(decisor)];
if (p.length) return falha('Mensagem bloqueada: ' + [...new Set(p)].join('; '));
return [{ json: { ok: true, mensagem: 'Aprovado: liberado para a fila (F3).', auditoria: { audit_id: aud.audit_id, qa_status: 'aprovado', qa_por: 'Thiago', qa_em: agora, qa_obs: obs, mensagem_aprovada: d1, mensagem_decisor: decisor },
  achados_status: 'aprovado', empresa: { company_id: aud.company_id, funil_etapa: 'F3', status_motivo: 'QA aprovado', atualizado_em: agora }, evento: evento('QA_APROVADO') } }];
